/// the same Cloud Calendars editor, independent of the destination calendar.
struct EventEditViewWrapper: View {
    let eventStore: EKEventStore
    let event: EKEvent
    var preferredColorScheme: ColorScheme? = nil
    var onEventUpdated: (() -> Void)? = nil

    var body: some View {
        AppLocalEventEditorView(
            target: AppLocalEventEditorTarget(
                eventKitEvent: event,
                startsInEditingMode: true
            ),
            onDismissed: onEventUpdated
        )
        .preferredColorScheme(preferredColorScheme)
    }

Section {
    Toggle("All-day", isOn: $isAllDay)
    CalendarDateTimePickerRow(title: "Starts", id: "start", selection: Binding(
        get: { startDate }, set: { value in
            let duration = max(0, endDate.timeIntervalSince(startDate))
            startDate = value
            endDate = value.addingTimeInterval(duration)
        }), showsTime: !isAllDay, expanded: $expandedDatePicker)
    CalendarDateTimePickerRow(title: "Ends", id: "end", selection: $endDate,
        range: startDate...Date.distantFuture, showsTime: !isAllDay,
        expanded: $expandedDatePicker)
    travelTimeMenu
}
.calendarDatePickerColumns([startDate, endDate])
.environment(\.timeZone, eventTimeZone)

Section {
    LabeledContent("Repeat") {
        Menu {
            ForEach(RepeatOption.allCases) { option in
                Button {
                    recurrencePattern = CalendarRecurrencePattern(rule: nil, start: startDate, calendar: eventCalendar)
                    repeatOption = option
                    repeatInterval = 1
                    if option == .never {
                        recurrenceEndDate = nil
                        expandedDatePicker = nil
                    }
                } label: {
                    if option == repeatOption && repeatInterval == 1 {
                        Label(option.title, systemImage: "checkmark")
                    } else {
                        Text(option.title)
                    }
                }
            }
            Button {
                recurrencePattern = CalendarRecurrencePattern(rule: nil, start: startDate, calendar: eventCalendar)
                repeatOption = .weekly
                repeatInterval = 2
            } label: {
                if repeatOption == .weekly && repeatInterval == 2 {
                    Label("Every 2 Weeks", systemImage: "checkmark")
                } else {
                    Text("Every 2 Weeks")
                }
            }
            Divider()
            Button("Custom…") {
                if repeatOption == .never { repeatOption = .daily }
                showCustomRecurrenceEditor = true
            }
        } label: {
            menuValueLabel(repeatDisplayText)
        }
        .tint(.secondary)
    }

    if repeatOption != .never {
        LabeledContent("End Repeat") {
            Menu {
                Button {
                    recurrenceEndDate = nil
                    expandedDatePicker = nil
                } label: {
                    if recurrenceEndDate == nil {
                        Label("Never", systemImage: "checkmark")
                    } else {
                        Text("Never")
                    }
                }
                Button {
                    if recurrenceEndDate == nil {
                        recurrenceEndDate = eventCalendar.date(
                            byAdding: .month,
                            value: 1,
                            to: startDate
                        ) ?? startDate
                    }
                } label: {
                    if recurrenceEndDate != nil {
                        Label("On Date", systemImage: "checkmark")
                    } else {
                        Text("On Date")
                    }
                }
            } label: {
                menuValueLabel(endRepeatDisplayText)
            }
            .tint(.secondary)
        }

        if recurrenceEndDate != nil {
            CalendarDateTimePickerRow(title: "End Date", id: "recurrence-end",
                selection: Binding(get: { recurrenceEndDate ?? startDate },
                    set: { recurrenceEndDate = $0 }),
                range: startDate...Date.distantFuture, showsTime: false,
                expanded: $expandedDatePicker)
                .environment(\.timeZone, eventTimeZone)

private var eventCalendar: Calendar {
    var calendar = Calendar(identifier: .gregorian)
    calendar.timeZone = eventTimeZone
    calendar.locale = appPreferences.presentationLocale
    return calendar
}

private var recurrenceRule: EKRecurrenceRule? {
    guard let frequency = repeatOption.frequency else { return nil }
    return recurrencePattern.rule(frequency: frequency, interval: repeatInterval, end: recurrenceEndDate)
}

private var eventTimeZone: TimeZone {
    if let identifier = existingLocalEvent?.timeZoneIdentifier,
       let timeZone = TimeZone(identifier: identifier) {
        return timeZone
    }
    return target.eventKitEvent?.timeZone ?? .autoupdatingCurrent
}

private func save() {
    guard selectedChoice?.canEdit == true else { return }
    do {
        let migratedBetweenStores = try persistSelectedDestination()
        EventNotificationManager.shared.rescheduleUpcomingEventNotifications()
        SharedEventSyncManager.eventStoreDidChange()
        NotificationCenter.default.post(name: .sharedEventImported, object: nil)
        // A cross-store move creates a new backing identifier. Close this
        // detail instance instead of leaving it bound to the removed one.
        if migratedBetweenStores {
            close()
        } else if !isNew && !target.startsInEditingMode {
            isEditing = false
        } else {
            close()
        }
    } catch {
        errorMessage = error.localizedDescription
    }
}

@discardableResult
private func saveAppLocalEvent() throws -> AppLocalEventRecord {
    guard localStore.calendar(id: selectedCalendarID)?.canEditEvents == true else {
        throw selectedCalendarUnavailableError()
    }
    let now = Date()
    let event = AppLocalEventRecord(
        id: existingLocalEvent?.id ?? "app-local-event:" + UUID().uuidString.lowercased(),
        calendarID: selectedCalendarID,
        title: title.trimmingCharacters(in: .whitespacesAndNewlines),
        startDate: persistedStartDate,
        endDate: persistedEndDate,
        isAllDay: isAllDay,
        location: location,
        notes: notes,
        urlString: urlString,
        videoCallURL: normalizedVideoCallURL,
        timeZoneIdentifier: existingLocalEvent?.timeZoneIdentifier
            ?? target.eventKitEvent?.timeZone?.identifier
            ?? TimeZone.current.identifier,
        alarms: [alertOffset.seconds, secondAlertOffset.seconds].compactMap { seconds in
            guard let seconds else { return nil }
            return AppLocalEventAlarm(relativeOffset: seconds)
        },
        createdAt: existingLocalEvent?.createdAt
            ?? target.eventKitEvent?.creationDate
            ?? now,
        updatedAt: now,
        remoteEventID: existingLocalEvent?.remoteEventID,
        isCancelled: existingLocalEvent?.isCancelled ?? false,
        travelTime: travelTime == .none ? nil : TimeInterval(travelTime.rawValue),
        recurrenceRules: recurrenceRule.map { [SharedEventRecurrenceRule(rule: $0)] },
        structuredLocation: structuredLocation,
        attachments: attachments
    )
    localStore.saveEvent(event)
    CalendarTravelReminderManager.shared.setEnabled(smartTravel && !isAllDay && structuredLocationCoordinate != nil,
        key: CalendarTravelReminderManager.key(localID: event.id), eventID: event.id,
        calendarID: event.calendarID, native: false, settings: travelSettings)

@discardableResult
private func saveEventKitEvent(showsSharePrompt: Bool = true) throws -> EKEvent {
    guard let calendar = eventStore.calendar(withIdentifier: selectedCalendarID),
          calendar.allowsContentModifications else {
        throw selectedCalendarUnavailableError()
    }
    let event = target.eventKitEvent ?? EKEvent(eventStore: eventStore)
    let wasNew = event.eventIdentifier == nil
    event.title = title.trimmingCharacters(in: .whitespacesAndNewlines)
    event.location = location
    event.structuredLocation = structuredLocation?.makeLocation(title: location)
    event.startDate = persistedStartDate
    event.endDate = persistedEndDate
    event.isAllDay = isAllDay
    event.calendar = calendar
    if event.timeZone == nil {
        event.timeZone = existingLocalEvent
            .flatMap { TimeZone(identifier: $0.timeZoneIdentifier) }
            ?? TimeZone.current
    }
    event.url = URL(string: urlString.trimmingCharacters(in: .whitespacesAndNewlines))
    event.notes = notes
    event.alarms = [alertOffset.seconds, secondAlertOffset.seconds].compactMap { seconds in
        guard let seconds else { return nil }
        return EKAlarm(relativeOffset: seconds)
    }
    event.recurrenceRules = recurrenceRule.map { [$0] }
    let span: EKSpan = event.eventIdentifier != nil && event.hasRecurrenceRules ? .futureEvents : .thisEvent
    try eventStore.save(event, span: span, commit: true)
    EventKitEventSupplementStore.update(
        travelTime: travelTime == .none ? nil : TimeInterval(travelTime.rawValue),
        attachments: attachments,
        videoCallURL: normalizedVideoCallURL,
        for: event

func saveEvent(_ event: AppLocalEventRecord) {
    var value = event
    value.endDate = max(value.endDate, value.startDate)
    value.updatedAt = Date()
    if let index = events.firstIndex(where: { $0.id == value.id }) {
        events[index] = value
    } else {
        events.append(value)
    }
    persistAndNotify()

/// Editable recurrence dimensions. Preserve imported rules until their pattern
/// is explicitly edited, including dimensions not exposed by Calendar's UI.
struct CalendarRecurrencePattern: Equatable {
    var weekdays: Set<Int>
    var monthDays: Set<Int>
    var months: Set<Int>
    var usesOrdinal = false
    var ordinal = 1
    var weekday = 1 // 1...7 weekdays; 8 every day; 9 weekdays; 10 weekend days
    var edited = false
    private let original: EKRecurrenceRule?

    init(rule: EKRecurrenceRule?, start: Date, calendar: Calendar) {
        original = rule
        weekdays = Set(rule?.daysOfTheWeek?.map { $0.dayOfTheWeek.rawValue } ?? [calendar.component(.weekday, from: start)])
        monthDays = Set(rule?.daysOfTheMonth?.map(\.intValue) ?? [calendar.component(.day, from: start)])
        months = Set(rule?.monthsOfTheYear?.map(\.intValue) ?? [calendar.component(.month, from: start)])
        usesOrdinal = (rule?.frequency == .monthly || rule?.frequency == .yearly) && rule?.daysOfTheWeek?.isEmpty == false
        if usesOrdinal {
            ordinal = rule?.setPositions?.first?.intValue ?? rule?.daysOfTheWeek?.first?.weekNumber ?? 1
            if ordinal == 0 { ordinal = 1 }
            switch weekdays {
            case Set(1...7): weekday = 8
            case Set(2...6): weekday = 9
            case Set([1, 7]): weekday = 10
            default: weekday = weekdays.sorted().first ?? 1
            }
        }
    }

    var signature: String {
        "\(weekdays.sorted())|\(monthDays.sorted())|\(months.sorted())|\(usesOrdinal)|\(ordinal)|\(weekday)|\(edited)"
    }

    func rule(frequency: EKRecurrenceFrequency, interval: Int, end: Date?) -> EKRecurrenceRule {
        if !edited, let original, original.frequency == frequency {
            return EKRecurrenceRule(recurrenceWith: frequency, interval: max(1, interval),
                daysOfTheWeek: original.daysOfTheWeek, daysOfTheMonth: original.daysOfTheMonth,
                monthsOfTheYear: original.monthsOfTheYear, weeksOfTheYear: original.weeksOfTheYear,
                daysOfTheYear: original.daysOfTheYear, setPositions: original.setPositions,
                end: end.map(EKRecurrenceEnd.init(end:)) ?? ((original.recurrenceEnd?.occurrenceCount ?? 0) > 0 ? original.recurrenceEnd : nil))
        }
        var days: [EKRecurrenceDayOfWeek]?
        var positions: [NSNumber]?
        if frequency == .weekly {
            days = weekdays.sorted().compactMap { EKWeekday(rawValue: $0).map { EKRecurrenceDayOfWeek($0) } }
        } else if (frequency == .monthly || frequency == .yearly) && usesOrdinal {
            let values = weekday == 8 ? Array(1...7) : weekday == 9 ? Array(2...6) : weekday == 10 ? [1, 7] : [weekday]
            days = values.compactMap { EKWeekday(rawValue: $0).map { EKRecurrenceDayOfWeek($0) } }
            positions = [NSNumber(value: ordinal)]
        }
        return EKRecurrenceRule(recurrenceWith: frequency, interval: max(1, interval),
            daysOfTheWeek: days,
            daysOfTheMonth: frequency == .monthly && !usesOrdinal ? monthDays.sorted().map(NSNumber.init(value:)) : nil,
            monthsOfTheYear: frequency == .yearly ? months.sorted().map(NSNumber.init(value:)) : nil,
